import groovy.json.JsonSlurper
import org.jahia.api.Constants
import org.jahia.services.content.JCRCallback
import org.jahia.services.content.JCRNodeWrapper
import org.jahia.services.content.JCRSessionWrapper
import org.jahia.services.content.JCRTemplate

import javax.jcr.NodeIterator
import javax.jcr.RepositoryException
import javax.jcr.Value
import javax.jcr.query.Query
import java.nio.charset.StandardCharsets
import java.util.Base64

final def logger = log
final String encodedMapping = [
        "",
        "",
        ""
].join("")
final Map<String, List<Map<String, Object>>> mapping = (Map<String, List<Map<String, Object>>>) new JsonSlurper().parseText(
        new String(Base64.decoder.decode(encodedMapping), StandardCharsets.UTF_8))
final Map<String, String> targetRoots = [
        blog: "contents/Blog/Entries",
        customerStories: "home/customer-stories",
        resources: "home/resources/livres-blancs-videos-autres"
]
final Map<String, List<String>> listFilters = [
        customerStories: [
                "/sites/systemsite/categories/industry",
                "/sites/systemsite/categories/topics"
        ],
        resources: [
                "/sites/systemsite/categories/resourcestypes",
                "/sites/systemsite/categories/topics"
        ]
]

for (String workspace : [Constants.EDIT_WORKSPACE, Constants.LIVE_WORKSPACE]) {
    JCRTemplate.getInstance().doExecuteWithSystemSession(
            null,
            workspace,
            new JCRCallback<Object>() {
                @Override
                Object doInJCR(JCRSessionWrapper session) throws RepositoryException {
                    Set<String> requiredCategoryPaths = mapping.values().flatten().collectMany {
                        Map<String, Object> item -> (List<String>) item.categoryPaths
                    }.toSet()
                    String canonicalRoot = "/sites/systemsite/categories"
                    String importedRoot = "${canonicalRoot}/categories"
                    List<String> missingCategoryPaths = requiredCategoryPaths.findAll {
                        String path -> !session.nodeExists(path)
                    }
                    List<String> unrecoverableCategoryPaths = missingCategoryPaths.findAll { String path ->
                        String importedPath = "${importedRoot}${path.substring(canonicalRoot.length())}"
                        !session.nodeExists(importedPath)
                    }
                    if (!unrecoverableCategoryPaths.isEmpty()) {
                        throw new RepositoryException(
                                "Required categories have no canonical or imported source in ${workspace}: " +
                                        unrecoverableCategoryPaths.join(', '))
                    }

                    int movedCategories = 0
                    missingCategoryPaths.sort { String path -> path.count('/') }.each { String path ->
                        if (!session.nodeExists(path)) {
                            String importedPath = "${importedRoot}${path.substring(canonicalRoot.length())}"
                            session.move(importedPath, path)
                            movedCategories++
                        }
                    }

                    int categorized = 0
                    int configuredLists = 0
                    for (String siteKey : ["mySite", "jahiacom"]) {
                        String siteRoot = "/sites/${siteKey}"
                        if (!session.nodeExists(siteRoot)) {
                            continue
                        }

                        for (Map.Entry<String, List<Map<String, Object>>> section : mapping.entrySet()) {
                            String rootPath = "${siteRoot}/${targetRoots[section.key]}"
                            if (!session.nodeExists(rootPath)) {
                                continue
                            }

                            Map<String, List<String>> expectedByName = section.value.collectEntries {
                                Map<String, Object> item -> [(item.name as String): (List<String>) item.categoryPaths]
                            }
                            String nodeType = section.key == "blog" ? "jahiacom:blogEntry" : "jnt:page"
                            NodeIterator targets = session.getWorkspace().getQueryManager()
                                    .createQuery(
                                            "SELECT * FROM [${nodeType}] WHERE ISDESCENDANTNODE('${rootPath}')",
                                            Query.JCR_SQL2)
                                    .execute()
                                    .getNodes()
                            List<String> unmapped = []
                            List<JCRNodeWrapper> nodes = []
                            while (targets.hasNext()) {
                                JCRNodeWrapper target = (JCRNodeWrapper) targets.nextNode()
                                nodes.add(target)
                                if (!expectedByName.containsKey(target.getName())) {
                                    List<String> existing = []
                                    if (target.hasProperty("j:defaultCategory")) {
                                        target.getProperty("j:defaultCategory").getValues().each { Value value ->
                                            try {
                                                existing.add(session.getNodeByIdentifier(value.getString()).getPath())
                                            } catch (RepositoryException ignored) {
                                                existing.add("<unresolved:${value.getString()}>")
                                            }
                                        }
                                    }
                                    unmapped.add("${target.getName()}=${existing}")
                                }
                            }
                            if (!unmapped.isEmpty()) {
                                throw new RepositoryException(
                                        "Docker category mapping is incomplete for ${workspace}: ${unmapped.join(', ')}")
                            }

                            for (JCRNodeWrapper target : nodes) {
                                List<String> categoryPaths = expectedByName[target.getName()]
                                if (!target.isNodeType("jmix:categorized")) {
                                    target.addMixin("jmix:categorized")
                                }
                                Value[] values = categoryPaths.collect { String path ->
                                    session.getValueFactory().createValue(session.getNode(path), true)
                                } as Value[]
                                target.setProperty("j:defaultCategory", values)
                                categorized++
                            }

                            if (listFilters.containsKey(section.key)) {
                                Value[] filterValues = listFilters[section.key].collect { String path ->
                                    session.getValueFactory().createValue(session.getNode(path), true)
                                } as Value[]
                                NodeIterator lists = session.getWorkspace().getQueryManager()
                                        .createQuery(
                                                "SELECT * FROM [jahiacom:listChildren] " +
                                                        "WHERE ISDESCENDANTNODE('${rootPath}')",
                                                Query.JCR_SQL2)
                                        .execute()
                                        .getNodes()
                                while (lists.hasNext()) {
                                    JCRNodeWrapper list = (JCRNodeWrapper) lists.nextNode()
                                    list.setProperty("categoryFilters", filterValues)
                                    configuredLists++
                                }
                            }
                        }
                    }

                    session.save()
                    logger.info(
                            "Category restoration completed in {}: {} content(s) categorized, " +
                                    "{} ListChildren component(s) configured, {} category branch(es) moved",
                            workspace,
                            categorized,
                            configuredLists,
                            movedCategories)
                    return null
                }
            })
}
